Here's a straightforward recursive-descent parser: the tokenizer rejects unknown characters and malformed numbers, and the grammar `expr → term (('+'|'-') term)*`, `term → unary (('*'|'/') unary)*`, `unary → '-' unary | atom`, `atom → number | '(' expr ')'` gives the required precedence (unary minus tighter than `*` and `/`, so `2 * -3` is legal but `2 + * 3` is not).

```python
def evaluate(expr: str) -> float:
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    # ---- tokenize ----
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
            continue
        if c.isdigit() or c == '.':
            j = i
            seen_dot = False
            seen_digit = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if seen_dot:
                        raise ValueError("malformed number in expression")
                    seen_dot = True
                else:
                    seen_digit = True
                j += 1
            if not seen_digit:
                raise ValueError("malformed number in expression")
            try:
                value = float(expr[i:j])
            except ValueError:
                raise ValueError("malformed number in expression")
            tokens.append(value)
            i = j
            continue
        raise ValueError("unknown character: %r" % c)

    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def parse_expr():
        nonlocal pos
        value = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        nonlocal pos
        value = parse_unary()
        while peek() in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs
        return value

    def parse_unary():
        nonlocal pos
        if peek() == '-':
            pos += 1
            return -parse_unary()
        return parse_atom()

    def parse_atom():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if isinstance(tok, float):
            pos += 1
            return tok
        if tok == '(':
            pos += 1
            value = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        raise ValueError("unexpected token: %r" % (tok,))

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token: %r" % (tokens[pos],))
    return float(result)


assert evaluate('2 + 3 * 4') == 14.0
assert evaluate('-(2 + 3) * 2') == -10.0
